const handleBgSync = async () => {
  setBgSyncing(true)
  setBgSyncResult(null)
  try {
    const res = await window.api.bgSyncClients()
    setBgSyncResult(`Background sync complete: ${res.synced}/${res.total} clients updated`)
  } catch {
    setBgSyncResult('Sync failed — check API key in Settings')
  } finally {
    setBgSyncing(false)
    setTimeout(() => setBgSyncResult(null), 5000)
  }
}

new_string:
// Starts the Companies House check of every client company, in the background (the same check
// that runs each day); what it finds appears under Activity.
const handleBgSync = async () => {
  setBgSyncing(true)
  setBgSyncResult(null)
  try {
    const res = await window.api.pulse.syncCompaniesHouse()
    if (!res.ok) setBgSyncResult(res.error)
    else if (res.data.started) setBgSyncResult(`Checking ${res.data.total} client compan${res.data.total === 1 ? 'y' : 'ies'} in the background. Changes appear under Activity.`)
    else setBgSyncResult(res.data.reason ?? 'Nothing to check.')
  } catch {
    setBgSyncResult('The check couldn’t start. Check the API key in Settings.')
  } finally {
    setBgSyncing(false)
    setTimeout(() => setBgSyncResult(null), 8000)
  }
}
